style.css:
@-moz-document regexp(".*") {
:root{
    --art-opacity: .45;          /* overall strength */
    --hue: 290;                   /* base hue (try 180 for teal, 340 for pink) */
    --speed: 50s;                 /* animation speed */
  }

  /* 3 stacked, click-through layers */
  html, body { background-color: #0b0b10 !important; }

  /* LAYER 1: slow, gooey nebula */
  body::before{
    content:"";
    position: fixed; inset: 0; pointer-events: none; z-index: 2147483637;
    opacity: var(--art-opacity);
    background:
      radial-gradient(60vmax 60vmax at 15% 20%, hsl(var(--hue) 90% 60%/.35), transparent 60%),
      radial-gradient(70vmax 70vmax at 85% 30%, hsl(calc(var(--hue)+60) 90% 60%/.35), transparent 65%),
      radial-gradient(80vmax 80vmax at 50% 85%, hsl(calc(var(--hue)-40) 90% 60%/.35), transparent 70%),
      linear-gradient(120deg, #111 0%, #0b0b10 60%, #111 100%);
    filter: saturate(1.1) blur(0.5px);
    animation: nebula var(--speed) ease-in-out infinite alternate;
    mix-blend-mode: screen;
  }

  /* LAYER 2: drifting starfield */
  body::after{
    content:"";
    position: fixed; inset: 0; pointer-events: none; z-index: 2147483638;
    opacity: calc(var(--art-opacity) * .9);
    background:
      radial-gradient(1px 1px at 10% 20%, #fff, transparent 2px),
      radial-gradient(1px 1px at 30% 80%, #fff, transparent 2px),
      radial-gradient(1px 1px at 60% 10%, #fff, transparent 2px),
      radial-gradient(1px 1px at 90% 40%, #fff, transparent 2px),
      radial-gradient(1px 1px at 70% 70%, #fff, transparent 2px),
      radial-gradient(1px 1px at 45% 50%, #fff, transparent 2px);
    background-size: 200% 200%;
    animation: stars calc(var(--speed) * .8) linear infinite;
    mix-blend-mode: screen;
  }

  /* LAYER 3: vaporwave grid at the bottom */
  html::before{
    content:"";
    position: fixed; left: -10vw; right: -10vw; bottom: -25vh; height: 80vh;
    pointer-events: none; z-index: 2147483636;
    background:
      repeating-linear-gradient( to right,
        hsl(var(--hue) 100% 70%/.45) 0 2px, transparent 2px 80px),
      repeating-linear-gradient( to top,
        hsl(calc(var(--hue)+40) 100% 70%/.45) 0 2px, transparent 2px 80px);
    transform: perspective(800px) rotateX(65deg);
    transform-origin: bottom center;
    mask-image: linear-gradient(to top, transparent 0%, black 25%, black 80%, transparent 100%);
    animation: grid var(--speed) linear infinite;
  }

  /* Gentle hover pop for links so pages still feel alive */
  a:hover { filter: drop-shadow(0 0 6px hsl(var(--hue) 100% 70%/0.6)); }

  @keyframes nebula{
    0%   { background-position: 0% 0%, 100% 0%, 50% 100%, 0 0; }
    100% { background-position: 100% 100%, 0% 60%, 60% 30%, 0 0; }
  }
  @keyframes stars{
    0%   { background-position: 0% 0%;   }
    100% { background-position: -200% -200%; }
  }
  @keyframes grid{
    0%   { background-position: 0 0, 0 0; }
    100% { background-position: 80px 0, 0 80px; }
  }
}
